<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>My Bookings | GoCycle</title><link rel="stylesheet" href="style.css"></head><body class="dashboard-body"><div class="app-shell"><aside class="sidebar"><a class="brand brand-link" href="dashboard.php">GO<span>CYCLE</span></a><p class="sidebar-label">MENU</p><a class="nav-link" href="dashboard.php">Dashboard</a><a class="nav-link" href="user_rides.php">Book a Ride</a><a class="nav-link active" href="user_bookings.php">My Bookings</a><a class="nav-link" href="user_account.php">My Account</a><div class="sidebar-bottom"><div class="sidebar-user"><div class="avatar"><?php echo strtoupper(substr($user['username'],0,1)); ?></div><div><strong><?php echo htmlspecialchars($user['username']); ?></strong><small>User</small></div></div><a class="nav-link logout-link" href="logout.php">→&nbsp;&nbsp; Log out</a></div></aside><main class="main-content"><header class="topbar"><div><p class="eyebrow">GOCYCLE / RESERVATIONS</p><h1>My Bookings</h1></div></header><section class="content-card"><div class="section-heading"><div><h3>Ride history</h3><p>View your reservations and cancel an upcoming ride when needed.</p></div><a class="primary-action" href="user_rides.php">Book a ride</a></div><?php if($notice): ?><div class="booking-notice <?php echo $notice_type==='error'?'error':'success'; ?>"><?php echo htmlspecialchars($notice); ?></div><?php endif; ?><div class="booking-table-wrap"><table class="admin-table booking-table"><thead><tr><th>Ride date</th><th>Time</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if($my_bookings && $my_bookings->num_rows>0): while($booking=$my_bookings->fetch_assoc()): $upcoming=$booking['status']==='Booked' && strtotime($booking['ride_date'].' '.$booking['ride_time'])>=time(); ?><tr><td><?php echo htmlspecialchars(date('F j, Y',strtotime($booking['ride_date']))); ?></td><td><?php echo htmlspecialchars(date('g:i A',strtotime($booking['ride_time']))); ?></td><td><span class="slot-status <?php echo $booking['status']==='Booked'?'available':'full'; ?>"><?php echo htmlspecialchars($booking['status']); ?></span></td><td><?php if($upcoming): ?><form method="post" action="ride_booking.php" onsubmit="return confirm('Cancel this ride booking?');"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars(csrf_token()); ?>"><input type="hidden" name="booking_action" value="cancel"><input type="hidden" name="booking_id" value="<?php echo (int)$booking['id']; ?>"><button class="cancel-booking-button" type="submit">Cancel booking</button></form><?php else: ?><span class="muted-text">—</span><?php endif; ?></td></tr><?php endwhile; else: ?><tr><td colspan="4" class="empty-bookings">No bookings yet. <a href="user_rides.php">Book your first ride</a>.</td></tr><?php endif; ?></tbody></table></div></section><footer class="page-footer">© 2026 GoCycle <span>Ride • Explore • Repeat</span></footer></main></div></body></html>
